module natural_sort
fn lower_ascii(c i64)i64{if c>=65&&c<=90{return c+32};return c}
fn natural_less(v &i64,offs &[64]int,lens &[64]int,pres &[64]int,a int,b int)bool{unsafe{mut lim:=pres[a];if pres[b]<lim{lim=pres[b]};for i in 0..lim{x:=lower_ascii(v[offs[a]+i]);y:=lower_ascii(v[offs[b]+i]);if x!=y{return x<y}};if pres[a]!=pres[b]{return pres[a]<pres[b]};sa,sb:=lens[a]-pres[a],lens[b]-pres[b];if sa==0||sb==0{return sa<sb};mut za:=0;mut zb:=0;for za<sa&&v[offs[a]+pres[a]+za]==48{za++};for zb<sb&&v[offs[b]+pres[b]+zb]==48{zb++};na,nb:=sa-za,sb-zb;if na!=nb{return na<nb};for i in 0..na{x:=v[offs[a]+pres[a]+za+i];y:=v[offs[b]+pres[b]+zb+i];if x!=y{return x<y}};return false}}
@[export: 'natural_sort']
pub fn natural_sort(v &i64,n usize,mut out &u8,cap usize)i64{unsafe{if v==nil||n<1||n>4161||v[0]<0||v[0]>64{return -1};count:=int(v[0]);mut offs:=[64]int{};mut lens:=[64]int{};mut pres:=[64]int{};mut order:=[64]int{};mut cursor:=1;mut total:=0;for i in 0..count{if cursor>=n||v[cursor]<0||v[cursor]>64{return -1};lens[i]=int(v[cursor]);cursor++;offs[i]=cursor;pres[i]=lens[i];mut digit:=false;for j in 0..lens[i]{c:=v[cursor+j];if c>=48&&c<=57{if j==0{return -1};if !digit{pres[i]=j;digit=true}}else if !((c>=65&&c<=90)||(c>=97&&c<=122))||digit{return -1}};cursor+=lens[i];total+=lens[i];order[i]=i};if cursor!=n{return -1};for i in 1..count{item:=order[i];mut j:=i;for j>0&&natural_less(v,&offs,&lens,&pres,item,order[j-1]){order[j]=order[j-1];j--};order[j]=item};mut bytes:=total;if count>0{bytes+=count-1};if bytes>cap||(bytes>0&&out==nil){return -2};mut w:=0;for i in 0..count{if i>0{out[w]=10;w++};k:=order[i];for j in 0..lens[k]{out[w]=u8(v[offs[k]+j]);w++}};return i64(w)}}
